{
    static int s_onLine = 0;
    int rawL, rawR, thL, thR, dL, dR, err, turn, left, right;
    int count = 0;
    int rawW, thW;

    SetLightSensorLed(lightL, 1);
    SetLightSensorLed(lightR, 1);
    SetWaitForTime(0.05);

    while (1)
    {
        rawL = GetLightSensor(lightL);
        rawR = GetLightSensor(lightR);
        thL = GetLightSensorThreshold(lightL);
        thR = GetLightSensorThreshold(lightR);
        if (thL < 50) thL = 700;
        if (thR < 50) thR = 700;

        dL = (thL - rawL) * 100 / thL;
        dR = (thR - rawR) * 100 / thR;
        if (dL < 0) dL = 0;
        if (dL > 100) dL = 100;
        if (dR < 0) dR = 0;
        if (dR > 100) dR = 100;

        rawW = GetLightSensor((unsigned char)watchPort);
        thW = GetLightSensorThreshold((unsigned char)watchPort);
        if (thW < 50) thW = 700;
        if (rawW < thW)
        {
            if (s_onLine == 0)
            {
                s_onLine = 1;
                count = count + 1;
                if (count >= number) break;
            }
        }
        else
        {
            s_onLine = 0;
        }

        err = dL - dR;
        turn = err / 3;
        left = speed - turn;
        right = speed + turn;
        if (left > 100) left = 100;
        if (left < -100) left = -100;
        if (right > 100) right = 100;
        if (right < -100) right = -100;
        SetMotor(motorL, left);
        SetMotor(motorR, right);

        SetWaitForTime(0.01);
    }
    SetMotor(motorL, 0);
    SetMotor(motorR, 0);
}

{
    static int s_turn = 0;
    int d, err, turn, left, right, t0;

    t0 = GetSysTime();
    while (1)
    {
        if (seconds > 0.0 && GetSysTime() - t0 >= (int)(seconds * 1000.0)) break;

        d = GetUltrasound(sonar);
        if (d >= 4 && d <= 180)
        {
            err = d - distCm;
            turn = err / 2;
            if (turn > 30) turn = 30;
            if (turn < -30) turn = -30;
            s_turn = turn;
        }

        left = speed + s_turn;
        right = speed - s_turn;
        if (left > 100) left = 100;
        if (left < -100) left = -100;
        if (right > 100) right = 100;
        if (right < -100) right = -100;
        SetMotor(motorL, left);
        SetMotor(motorR, right);
        SetWaitForTime(0.02);
    }
    SetMotor(motorL, 0);
    SetMotor(motorR, 0);
}

