{
    static int s_lastErr = 0;
    int rawL, rawR, thL, thR, dL, dR, err, turn, left, right;

    SetLightSensorLed(lightL, 1);
    SetLightSensorLed(lightR, 1);
    SetWaitForTime(0.05);

    while (1)
    {
        rawL = GetLightSensor(lightL);
        rawR = GetLightSensor(lightR);
        thL = GetLightSensorThreshold(lightL);
        thR = GetLightSensorThreshold(lightR);
        if (thL < 50) thL = 700;
        if (thR < 50) thR = 700;

        dL = (thL - rawL) * 100 / thL;
        dR = (thR - rawR) * 100 / thR;
        if (dL < 0) dL = 0;
        if (dL > 100) dL = 100;
        if (dR < 0) dR = 0;
        if (dR > 100) dR = 100;

        if (dL < 10 && dR < 10)
        {
            SetMotor(motorL, 0);
            SetMotor(motorR, 0);
            SetInBeep(ON);
            SetWaitForTime(0.3);
            SetInBeep(OFF);
            break;
        }

        err = dL - dR;
        turn = err * 2 + (err - s_lastErr);
        s_lastErr = err;
        left = speed - turn;
        right = speed + turn;
        if (left > 100) left = 100;
        if (left < -100) left = -100;
        if (right > 100) right = 100;
        if (right < -100) right = -100;
        SetMotor(motorL, left);
        SetMotor(motorR, right);

        SetWaitForTime(0.01);
    }
    SetMotor(motorL, 0);
    SetMotor(motorR, 0);
}

{
    static int s_onLine = 0;
    int r3, r4, r5, f3, f4, f5, rw, fw, err, turn, left, right;
    int count = 0;

    /* 通道 n 相对光值 = GetTraceV2I2C(端口, n)；参考值 = GetTraceV2I2C(端口, 10+n) */
    /* 相对光值 < 参考值 视为压到线（极性若相反请对调两处比较） */
    while (1)
    {
        r3 = GetTraceV2I2C(tracePort, 3);
        r4 = GetTraceV2I2C(tracePort, 4);
        r5 = GetTraceV2I2C(tracePort, 5);
        f3 = GetTraceV2I2C(tracePort, 13);
        f4 = GetTraceV2I2C(tracePort, 14);
        f5 = GetTraceV2I2C(tracePort, 15);

        rw = GetTraceV2I2C(tracePort, sensor);
        fw = GetTraceV2I2C(tracePort, 10 + sensor);
        if (rw < fw)
        {
            if (s_onLine == 0)
            {
                s_onLine = 1;
                count = count + 1;
                if (count >= number) break;
            }
        }
        else
        {
            s_onLine = 0;
        }

        /* 中央三通道压线加权：4 号压线=线在中央不偏差；3 压线=线偏左；5 压线=线偏右 */
        err = 0;
        if (r3 < f3) err = err + 2;
        if (r5 < f5) err = err - 2;
        turn = err * 8;

        left = speed - turn;
        right = speed + turn;
        if (left > 100) left = 100;
        if (left < -100) left = -100;
        if (right > 100) right = 100;
        if (right < -100) right = -100;
        SetMotor(motorL, left);
        SetMotor(motorR, right);

        SetWaitForTime(0.01);
    }
    SetMotor(motorL, 0);
    SetMotor(motorR, 0);
}

{
    long baseL, baseR, cl, cr;

    SetMotorCode(motorL);
    SetMotorCode(motorR);
    baseL = GetMotorCode(motorL);
    baseR = GetMotorCode(motorR);

    while (1)
    {
        cl = GetMotorCode(motorL) - baseL;
        if (cl < 0) cl = -cl;
        cr = GetMotorCode(motorR) - baseR;
        if (cr < 0) cr = -cr;
        if (cl >= target && cr >= target) break;

        SetMotor(motorL, -speed);
        SetMotor(motorR, speed);
    }
    SetMotor(motorL, 0);
    SetMotor(motorR, 0);
}
